import json
import time
from contextlib import nullcontext
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

import aiohttp
import structlog
from pydantic import BaseModel, StrictBool, StrictStr, ValidationError

from rasa.builder.copilot.mcp_server.constants import (
    LLM_MESSAGE_CONTENT,
    LLM_ROLE,
    LLM_ROLE_ASSISTANT,
    LLM_ROLE_SYSTEM,
    LLM_ROLE_USER,
    SIM_EVAL_LLM_MAX_ATTEMPTS,
    SIM_EVAL_RETRY_BACKOFF_FACTOR,
    SIMULATOR_MAX_TURNS,
)
from rasa.builder.copilot.mcp_server.prompts.prompt_loader import (
    copilot_jinja_env,
    get_simulated_user_system_prompt_template,
)
from rasa.builder.copilot.mcp_server.tools.scenario import Scenario
from rasa.shared.providers.llm.llm_client import LLMClient
from rasa.shared.utils.llm import (
    get_model_and_provider,
    supports_json_response_format,
    supports_response_schema,
)


class SimulatedUserReply(BaseModel):
    """Validated JSON payload returned by the LLM user simulator."""

    message: StrictStr
    done: StrictBool


@dataclass(frozen=True)
class BotReplyMetrics:
    """Bot reply text and perceived-latency timings from one REST stream.

    ``turn_latency_ms`` is stamped when the last ``text`` NDJSON line arrives,
    not when the HTTP stream closes, so post-reply server work (e.g. tracker
    save, ``discover_facts``) is excluded from perceived reply latency.
    """

    texts: List[str]
    ttft_ms: Optional[float]
    turn_latency_ms: Optional[float]


# Keys for turns and transcript
_TURN = "turn"
_BOT = "bot"
_USER = "user"
_TTFT_MS = "ttft_ms"
_TURN_LATENCY_MS = "turn_latency_ms"

# Turn prompts
_SIMULATOR_OPENING_TURN_PROMPT = (
    "(The conversation is starting. Send your opening message as the user.)"
)
_SIMULATOR_TURN_PROMPT = "Bot: {bot_text}\n\nYour reply (as the user):"

# Timeout for sending messages to the Rasa server
_SEND_MESSAGE_TIMEOUT = 30.0

# JSON array from the classic REST webhook (no ``stream=true``).
_JSON_CONTENT_TYPES = frozenset({"application/json", "text/json"})


class _UnparseableStreamBody(Exception):
    """Raised when a ``stream=true`` body is neither NDJSON nor a JSON array."""


structlogger = structlog.get_logger()


async def run_text_simulation(
    scenario: Scenario,
    llm_client: LLMClient,
    session: aiohttp.ClientSession,
    conversation_id: str,
    rasa_url: str,
    prompt_template: str = get_simulated_user_system_prompt_template(),
    max_turns: int = SIMULATOR_MAX_TURNS,
    initial_bot_messages: Optional[List[str]] = None,
    llm_semaphore: Optional[asyncio.Semaphore] = None,
) -> List[Dict[str, Any]]:
    """Drive the text user/bot turn loop and return simulated turns.

    Owns the LLM conversation history: builds the system prompt from
    ``scenario``, appends user and assistant messages each turn, and
    selects the correct turn prompt (opening vs. follow-up). Stops
    when the simulated user sets ``done=True``, sends an empty
    message, the bot returns no response, or ``max_turns`` is reached.

    The caller owns the wider HTTP lifecycle: creating the
    conversation id, opening the ``aiohttp.ClientSession``, bootstrapping
    session start, injecting initial slots, and fetching the tracker afterward.

    Args:
        scenario: ``Scenario`` model instance used to build the
            simulator system prompt from its
            ``simulation_context`` attribute.
        llm_client: LLM client driving the simulated user.
        session: Open ``aiohttp.ClientSession`` used to send
            messages to the Rasa server.
        conversation_id: Rasa conversation (sender) id.
        rasa_url: Base URL of the running Rasa server.
        prompt_template: LLM system prompt template for the user simulator. It will be
            rendered with the scenario's ``simulation_context``.
        max_turns: Maximum number of user/bot turns before stopping.
        llm_semaphore: Optional ceiling on concurrent simulation-role provider
            calls, shared across every run in the batch. ``None`` leaves the
            calls unbounded.
        initial_bot_messages: Optional welcome (or other) bot texts from a
            prior ``/session_start`` bootstrap. When non-empty, the first
            simulator turn uses the follow-up prompt with those texts so the
            opening user message replies to the welcome. The welcome is
            prepended as a bot-only turn (empty ``user``) so judges and run
            reports include it in the transcript without inventing a user line.

    Returns:
        A list of turn dicts, each with ``turn``, ``user``, ``bot``,
        ``ttft_ms``, and ``turn_latency_ms`` keys.
    """
    llm_history: List[Dict[str, str]] = [
        {
            LLM_ROLE: LLM_ROLE_SYSTEM,
            LLM_MESSAGE_CONTENT: _build_simulated_user_system_prompt(
                scenario, prompt_template
            ),
        }
    ]
    bot_messages = initial_bot_messages or []
    turns: List[Dict[str, Any]] = []
    if initial_bot_messages:
        turns.append(
            {
                _TURN: 0,
                _USER: "",
                _BOT: initial_bot_messages,
            }
        )
    completion_kwargs = _user_simulator_completion_kwargs(
        llm_client, conversation_id=conversation_id
    )

    for turn_num in range(max_turns):
        if bot_messages:
            bot_text = " ".join(bot_messages)
            prompt = _SIMULATOR_TURN_PROMPT.format(
                bot_text=bot_text,
            )
        else:
            prompt = _SIMULATOR_OPENING_TURN_PROMPT
        llm_history.append({LLM_ROLE: LLM_ROLE_USER, LLM_MESSAGE_CONTENT: prompt})

        reply = await _generate_user_message(
            llm_client,
            llm_history,
            completion_kwargs=completion_kwargs,
            conversation_id=conversation_id,
            llm_semaphore=llm_semaphore,
        )

        llm_history.append(
            {LLM_ROLE: LLM_ROLE_ASSISTANT, LLM_MESSAGE_CONTENT: reply.message}
        )

        user_message = reply.message
        if not user_message.strip():
            break

        reply_metrics = await _send_message(
            session, conversation_id, user_message, rasa_url
        )
        bot_messages = reply_metrics.texts
        turns.append(
            {
                _TURN: turn_num + 1,
                _USER: user_message,
                _BOT: bot_messages,
                _TTFT_MS: reply_metrics.ttft_ms,
                _TURN_LATENCY_MS: reply_metrics.turn_latency_ms,
            }
        )

        if reply.done or not bot_messages:
            break

    return turns


async def _send_message(
    session: aiohttp.ClientSession,
    conversation_id: str,
    text: str,
    rasa_url: str,
    *,
    metadata: Optional[Dict[str, Any]] = None,
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
    timeout: float = _SEND_MESSAGE_TIMEOUT,
) -> BotReplyMetrics:
    """Send a user message over the REST SSE stream and return bot reply metrics.

    Prefers ``?stream=true`` so perceived latency (time to first bot text and
    full turn duration) can be measured at the simulated client.

    A classic JSON-array body on the stream request is parsed in place. An
    HTTP 200 whose body is neither NDJSON nor a JSON array fails this turn
    immediately: the webhook already processed the message, so retrying or
    posting again without ``stream`` would duplicate the turn. HTTP errors,
    connection failures, and timeouts still retry the streaming request with
    linear backoff.

    Args:
        session: Open ``aiohttp.ClientSession``.
        conversation_id: Rasa conversation (sender) id.
        text: User message text.
        rasa_url: Base URL of the running Rasa server.
        metadata: Optional webhook metadata; defaults to ``is_simulation`` only.
        max_attempts: Total tries before giving up.
        timeout: Per-request timeout in seconds.

    Returns:
        ``BotReplyMetrics`` with assembled bot text and optional latency fields.

    Raises:
        RuntimeError: when the stream returns HTTP 200 with an unparseable
            body, or when all retry attempts are exhausted.
    """
    url = f"{rasa_url.rstrip('/')}/webhooks/rest/webhook"
    payload_metadata: Dict[str, Any] = (
        dict(metadata) if metadata is not None else {"is_simulation": True}
    )
    payload = {
        "sender": conversation_id,
        "message": text,
        "metadata": payload_metadata,
    }
    last_error: Optional[str] = None
    client_timeout = aiohttp.ClientTimeout(total=timeout)

    for attempt in range(1, max_attempts + 1):
        try:
            t0 = time.perf_counter()
            async with session.post(
                url,
                params={"stream": "true"},
                json=payload,
                timeout=client_timeout,
            ) as resp:
                resp.raise_for_status()
                try:
                    return await _read_preferred_bot_reply(resp, t0)
                except _UnparseableStreamBody as exc:
                    structlogger.error(
                        "rasa.simulation.send_message.unparseable_stream_body",
                        error=repr(exc),
                    )
                    raise RuntimeError(
                        "send_message received HTTP 200 with an unparseable "
                        f"stream body: {exc}"
                    ) from exc
        except RuntimeError:
            raise
        except Exception as exc:
            last_error = repr(exc)
            structlogger.warning(
                "rasa.simulation.send_message.failed",
                attempt=attempt,
                max_attempts=max_attempts,
                error=last_error,
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.simulation.send_message.exhausted",
        max_attempts=max_attempts,
        error=last_error,
    )
    raise RuntimeError(
        f"send_message failed after {max_attempts} " f"attempts: {last_error}"
    )


async def _read_preferred_bot_reply(
    resp: aiohttp.ClientResponse,
    t0: float,
) -> BotReplyMetrics:
    """Parse a ``stream=true`` response as NDJSON, or as a JSON array body."""
    if resp.content_type in _JSON_CONTENT_TYPES:
        return await _read_unary_bot_reply(resp, t0)
    return await _read_streaming_bot_reply(resp, t0)


async def _read_unary_bot_reply(
    resp: aiohttp.ClientResponse,
    t0: float,
) -> BotReplyMetrics:
    """Parse a classic REST JSON-array webhook body."""
    try:
        data = await resp.json(content_type=None)
    except (aiohttp.ContentTypeError, ValueError) as exc:
        raise _UnparseableStreamBody(repr(exc)) from exc
    texts = _texts_from_rest_payload(data)
    if texts is None:
        raise _UnparseableStreamBody("response JSON is not a list of messages")
    return BotReplyMetrics(
        texts=texts,
        ttft_ms=None,
        turn_latency_ms=(time.perf_counter() - t0) * 1000,
    )


def _texts_from_rest_payload(data: Any) -> Optional[List[str]]:
    """Return bot texts from a REST JSON array, or ``None`` if the shape is wrong."""
    if not isinstance(data, list):
        return None
    return [msg["text"] for msg in data if isinstance(msg, dict) and msg.get("text")]


async def _read_streaming_bot_reply(
    resp: aiohttp.ClientResponse,
    t0: float,
) -> BotReplyMetrics:
    """Parse NDJSON lines from a REST SSE response and record latency timings.

    All ``text`` payloads in the stream are concatenated into a single bot
    reply for the turn. Multi-message turns are not split on the client;
    see tracker ``BotUttered`` events when per-utterance fidelity is needed.

    ``turn_latency_ms`` is updated on every ``text`` event so multi-message
    turns measure time until the final bot text, excluding work after the
    last visible reply when the stream stays open until ``handle_message``
    completes.

    A JSON-array body (classic non-stream webhook) is accepted from the same
    response. Any other unparseable body raises ``_UnparseableStreamBody``.

    Concatenated ``texts`` are only a prompt/fallback view of the stream.
    Evaluation overlays tracker ``BotUttered`` events onto ``turn.bot`` so
    the judge sees utterance boundaries.
    """
    reply = _NdjsonReplyReader(t0)
    raw = b""

    async for chunk in resp.content.iter_any():
        raw += chunk
        if not reply.failed:
            reply.feed(chunk)

    reply.flush()
    if reply.failed:
        return _metrics_from_buffered_rest_body(raw, t0)
    return reply.metrics()


_NDJSON_SKIP = object()
_NDJSON_FAIL = object()


class _NdjsonReplyReader:
    """Accumulates NDJSON stream events into one bot reply with timings.

    Once a line fails to parse the reader stops consuming: the caller falls
    back to parsing the fully buffered body as a classic REST JSON array.
    """

    def __init__(self, t0: float) -> None:
        self.failed = False
        self._t0 = t0
        self._buffer = b""
        self._text_parts: List[str] = []
        self._ttft_ms: Optional[float] = None
        self._turn_latency_ms: Optional[float] = None

    def feed(self, chunk: bytes) -> None:
        """Consume every complete NDJSON line available in ``chunk``."""
        self._buffer += chunk
        while b"\n" in self._buffer:
            line, self._buffer = self._buffer.split(b"\n", 1)
            if not self._consume(line):
                return

    def flush(self) -> None:
        """Consume a final object that arrived without a trailing newline."""
        if self.failed or not self._buffer.strip():
            return
        self._consume(self._buffer)
        self._buffer = b""

    def metrics(self) -> BotReplyMetrics:
        """Return the assembled reply, defaulting latency to the read duration."""
        turn_latency_ms = self._turn_latency_ms
        if turn_latency_ms is None:
            turn_latency_ms = (time.perf_counter() - self._t0) * 1000
        assembled = "".join(self._text_parts)
        return BotReplyMetrics(
            texts=[assembled] if assembled else [],
            ttft_ms=self._ttft_ms,
            turn_latency_ms=turn_latency_ms,
        )

    def _consume(self, line: bytes) -> bool:
        """Parse one line; return ``False`` once the stream is unparseable."""
        parsed = _parse_ndjson_line(line)
        if parsed is _NDJSON_FAIL:
            self.failed = True
            return False
        if parsed is not _NDJSON_SKIP:
            self._record(parsed.get("text"))
        return True

    def _record(self, event_text: Optional[str]) -> None:
        if not event_text:
            return
        now_ms = (time.perf_counter() - self._t0) * 1000
        if self._ttft_ms is None:
            self._ttft_ms = now_ms
        self._turn_latency_ms = now_ms
        self._text_parts.append(event_text)


def _parse_ndjson_line(line: bytes) -> Any:
    """Decode one NDJSON line into a dict, or a skip/fail sentinel."""
    try:
        line_str = line.decode().strip()
    except UnicodeDecodeError:
        return _NDJSON_FAIL
    if not line_str:
        return _NDJSON_SKIP
    try:
        event = json.loads(line_str)
    except json.JSONDecodeError:
        return _NDJSON_FAIL
    if isinstance(event, list):
        return _NDJSON_FAIL
    if not isinstance(event, dict):
        return _NDJSON_FAIL
    return event


def _metrics_from_buffered_rest_body(raw: bytes, t0: float) -> BotReplyMetrics:
    """Parse a fully buffered body as a REST JSON array, or raise."""
    try:
        data = json.loads(raw.decode())
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise _UnparseableStreamBody(repr(exc)) from exc
    texts = _texts_from_rest_payload(data)
    if texts is None:
        raise _UnparseableStreamBody("response JSON is not a list of messages")
    return BotReplyMetrics(
        texts=texts,
        ttft_ms=None,
        turn_latency_ms=(time.perf_counter() - t0) * 1000,
    )


def _build_simulated_user_system_prompt(
    scenario: Scenario, prompt_template: str
) -> str:
    """Build the system prompt for the LLM user simulator."""
    return (
        copilot_jinja_env()
        .from_string(prompt_template)
        .render(
            simulation_context=scenario.simulation_context,
        )
    )


def _user_simulator_completion_kwargs(
    llm_client: LLMClient,
    *,
    conversation_id: str,
) -> Dict[str, Any]:
    """Return per-call LLM kwargs for the user simulator.

    Prefer provider-side schema enforcement when available. Fall back
    to plain JSON-object mode for models that support syntactic JSON
    but not schemas. Capabilities are model-level, not turn-level, so
    callers should compute these kwargs once per simulation and reuse
    them for every turn.
    """
    model, _ = get_model_and_provider(llm_client)
    schema_supported = supports_response_schema(llm_client)
    if schema_supported:
        structlogger.debug(
            "rasa.simulation.user_simulator.structured_output",
            conversation_id=conversation_id,
            mode="pydantic_schema",
            model=model,
        )
        return {"response_format": SimulatedUserReply}

    json_mode_supported = supports_json_response_format(llm_client)
    structlogger.debug(
        "rasa.simulation.user_simulator.structured_output",
        conversation_id=conversation_id,
        mode="json_object" if json_mode_supported else "prompt_only",
        model=model,
    )
    if json_mode_supported:
        return {"response_format": {"type": "json_object"}}
    return {}


def _validate_simulator_reply(
    payload: Any,
) -> Optional[SimulatedUserReply]:
    """Validate a parsed simulator payload without coercing types."""
    if not isinstance(payload, dict):
        return None
    try:
        return SimulatedUserReply.model_validate(payload)
    except ValidationError:
        return None


def _parse_simulator_response(
    raw: str,
) -> Optional[SimulatedUserReply]:
    """Parse the user-simulator's JSON reply, tolerant of trailing junk.

    Tries strict ``json.loads`` first, then falls back to
    ``raw_decode`` which ignores trailing garbage after the first
    valid JSON object. Returns ``None`` when neither strategy
    produces a valid ``SimulatedUserReply``, signaling the caller
    to retry.
    """
    if not raw:
        return None

    try:
        return _validate_simulator_reply(json.loads(raw))
    except json.JSONDecodeError:
        pass

    start = raw.find("{")
    if start >= 0:
        try:
            obj, _ = json.JSONDecoder().raw_decode(raw[start:])
            return _validate_simulator_reply(obj)
        except json.JSONDecodeError:
            pass

    return None


async def _generate_user_message(
    llm_client: LLMClient,
    messages: List[Dict[str, str]],
    completion_kwargs: Optional[Dict[str, Any]] = None,
    *,
    conversation_id: str,
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
    llm_semaphore: Optional[asyncio.Semaphore] = None,
) -> SimulatedUserReply:
    """Call the LLM to get simulated user message and return a validated reply.

    This function does **not** mutate ``messages``; the caller is
    responsible for appending the reply to the conversation history
    so it retains full control over state.

    Args:
        llm_client: LLM client used to generate the simulated user
            message.
        messages: Full chat-completion message list the caller has
            already assembled (system prompt, prior turns, and the
            latest user-prompt entry).
        completion_kwargs: Extra keyword arguments forwarded to
            ``llm_client.acompletion`` (e.g. ``response_format``).
            Should be computed once via
            ``_user_simulator_completion_kwargs`` and reused for
            every turn.
        conversation_id: Simulation conversation id for structured
            debug logs.
        max_attempts: Number of retries on LLM call failures or
            unparseable responses before giving up.
        llm_semaphore: Optional ceiling on concurrent simulation-role provider
            calls, held only while a request is in flight so retry backoff
            does not occupy a slot. ``None`` leaves the calls unbounded.

    Returns:
        A validated ``SimulatedUserReply`` with ``.message`` and
        ``.done`` fields.

    Raises:
        RuntimeError: after all retry attempts are exhausted.
    """
    extra_kwargs = completion_kwargs or {}
    structlogger.debug(
        "rasa.simulation.user_simulator.prompt",
        conversation_id=conversation_id,
        messages=messages,
    )
    last_error: Optional[str] = None
    for attempt in range(1, max_attempts + 1):
        try:
            async with llm_semaphore or nullcontext():
                response = await llm_client.acompletion(messages, **extra_kwargs)
            raw = response.choices[0].strip()
            parsed = _parse_simulator_response(raw)
            if parsed is not None:
                return parsed
            last_error = f"could not parse simulator reply: {raw!r}"
            structlogger.debug(
                "rasa.simulation.user_simulator.parse_failed",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                raw=raw,
            )
        except Exception as exc:
            last_error = repr(exc)
            structlogger.warning(
                "rasa.simulation.user_simulator.call_failed",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error=last_error,
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.simulation.user_simulator.exhausted",
        conversation_id=conversation_id,
        max_attempts=max_attempts,
        error=last_error,
    )
    raise RuntimeError(
        f"user simulator failed after {max_attempts} " f"attempts: {last_error}"
    )
